head.script:
/**
* PSP007F03.xml(소송비용계산 - 인지액 계산)
* ASIS-ECF304_1.jsp, ECF304_1.js
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.28.   김기오       [NELS]최초 생성
*  2024.02.27.   김기오       소송유형 변경 EVENT 수정(임시지위시 STRING CONCAT 추가)
* ============= ============ ==========================
*/

/* ==================================
 * 1.전역변수 선언부
 * ==================================*/
// 문구정보
scwin.phrsInfo = {
    elctnDiscGuide: " 부터 전자소송으로 소장을 제출하는 경우에는 종이소송에 비하여 10% 할인된 인지액을 납부하시면 됩니다.",

    ptntGuideTxt1: "7. 특허소송은 모든 사건의 소송목적 가액이 ",
    ptntGuideTxt2: " 원으로 정해져 있습니다. 따라서 소제기 시 인지액은 ",
    ptntGuideTxt3: "원으로 모든 사건에 동일하게 적용됩니다.",

    ptntApplGuideTxt1: "8. 특허상고장은 종이소장 인지액 기준 금액의 2배에 해당하는 금액의 90%를 인지액으로 납부하셔야 합니다. 따라서 특허상고장 일 경우 ",
    ptntApplGuideTxt2: "원을 인지액으로 납부하셔야 합니다.",
}
//인지액계산정보
scwin.stmpAmtCalcInfo = {
    injiNm: "", // 인지액명

    injiCalcByAmt: "",// 금액대별 인지액 계산식
    injiCalcBySim: "",// 심급별 인지액 배수식
    cmbSoType: "",

    injiHanggoAmt: "", //(재)항고
    cmbHanggoType: "",

    injiSinAmt: "", //신청사건
    cmbSinType: "",
    injiWptAmt: "", //특허사건
    injiCalcBySimWCV: "", //민사 사건 종류
    injiHanggoAmtWCV: "", //민사 대상사건 종류
    injiSinAmtWCV: "", //민사 신청사건 종류

    injiCalcBySimWPT: "", //특허 사건 종류
    injiHanggoAmtWPT: "", //특허 대상사건 종류
    injiSinAmtWPT: "", //특허 신청사건 종류

    injiCalcBySimWHS: "", //행정 사건 종류
    injiHanggoAmtWHS: "", //행정 대상사건 종류
    injiSinAmtWHS: "", //행정 신청사건 종류

    injiCalcBySimWHP: "", //회생파산 사건 종류
    injiSinAmtWHP1: "", //회생파산 신청사건 종류
    injiSinAmtWHP2: "",
    injiSinAmtWHP3: "",
    injiSinAmtWHP4: "",
    injiSinAmtWHP5: "",

    injiCalcBySimJHWGJ: "", //민사집행 사건 종류
    injiHanggoAmtJHWGJ: "", //민사집행 항고사건 종류
    injiSinAmtJHWGJ1: "", //민사집행 신청사건 종류
    injiSinAmtJHWGJ2: "",
    injiSinAmtJHWGJ3: "",
    injiSinAmtJHWGJ4: "",
    injiSinAmtJHWGJ5: "",
    injiSinAmtJHWGJ6: "",

    injiCalcBySimGW: "", //과태료 사건 종류
    injiHanggoAmtGW: "", //과태료 항고사건 종류
    injiSinAmtGW1: "", //과태료 신청사건 종류

    injiCalcBySimWETBS: "", //비송 사건 종류
    injiHanggoAmtWETBS: "", //비송 항고사건 종류
    injiSinAmtWETBS1: "", //비송 신청사건 종류
    injiSinAmtWETBS2: "",

    //화면load시 불러오는 데이터
    stmpDiscRate: "", //전자소송인지액 할인률
    stmpDiscEnfcYmd: "", //전자소송인지액 할인 시행일자

    vsmlDisp: "",
    vsmlTxt: "",
    stmpDisp: "",
    stmpDispSg: "",

    openPage: "",

}

/* ==================================
* 2.페이지 Onload/Unload 선언부
* ==================================*/
/**
 * 화면 pageload 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */

scwin.onpageload = function () {
    _debug("[PSP007F03#onpageload] 로드됨. frame ID : " + $p.getFrameId() + " ");
    // var wfparam = psp.getSubPageInit($p);
    // debugger;
    // dma_parentInfo.setJSON(psp.componentById("dma_parentInfo", "pfwork"));
    //_debug("[PSP007F03#onpageload]", "<page param>", wfparam);

    scwin.init();
}

scwin.onpageunload = function () {

};

/* ==================================
 * 3.페이지 초기화 선언부
 * ==================================*/
/**
* 페이지 초기화
*
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.28.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.init = function () {
    //부모창으로부터 데이터 전달
    dma_parentInfo.setJSON($p.parent().dma_parentInfo.getJSON());
    //기본적으로 민사세팅
    if (scutilo.isEmpty(dma_parentInfo.get("elctnLwstTaskTypCd"))) {
        dma_parentInfo.set("elctnLwstTaskTypCd", "PCV");
    }

    //화면Load 시 첫 번째 입력필드에 마우스커스 포커스
    sbx_elctnLwstTaskTypCd.focus();
    //인지액계산 기본정보 조회
    scwin.retrieveStmpCalcBasInfo();
};

/* ==================================
* 4.컴포넌트 이벤트 처리부
* ==================================*/

/**
 * 소송유형 selectBox onviewchange Event
 * ASIS-fnChgSosongTypcd 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_elctnLwstTaskTypCd_onviewchange = function (info) {
    scwin.fnChangeLwstTaskTypCd();
};

/**
 * 사건종류 selectBox onviewchange Event
 * ASIS-fnSoTypeChange 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_csType_onviewchange = function (info) {
    scwin.fnChangeCsTypCd();
};

/**
 * 대상사건 종류 selectBox onviewchange Event
 * ASIS-fnHanggoTypeChange 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_apalDetailCsType_onviewchange = function (info) {
    scwin.fnChangeApalTrgtCsType();
};

/**
 * 신청사건 종류 selectBox onviewchange Event
 * ASIS-fnSinTypeChange 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_aplyDetailCsType_onviewchange = function (info) {
    scwin.fnChangeAplyCsType();
};

/**
 * 계산(집행권원)버튼 onclick Event
 * ASIS-fnCalcIjAmt1 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_spclCalc_onclick = function (e) {
    scwin.fnSpclCalc();
};

/**
 * 계산(소가)버튼 onclick Event
 * ASIS-fnCalcIjAmt 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_normCalc_onclick = function (e) {
    scwin.fnNormCalc();
};

/**
 * 사용증명원 inputBox onkeyup Event
 * ASIS-fnInputAmtMoney 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_useCertf_onkeyup = function (e) {
    scwin.fnChkVsmlInput("useCertf", e);
};

/**
 * 집행권원 inputBox onkeyup Event
 * ASIS-fnInputAmtMoney 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_schld_onkeyup = function (e) {
    scwin.fnChkVsmlInput("schld", e);
};

/**
 * 소가 inputBox onkeyup Event
 * ASIS-fnInputAmtMoney 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_vsml_onkeyup = function (e) {
    scwin.fnChkVsmlInput("vsml", e);
};

/**
 * 사용증명원 inputBox onkeyDown Event
 * ASIS-fnCalcIjAmt1 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_useCertf_onkeydown = function (e) {
    if (e.keyCode == "13") {
        e.preventDefault();
        scwin.fnSpclCalc();
    }
};

/**
 * 집행권원 inputBox onkeyDown Event
 * ASIS-fnCalcIjAmt1 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_schld_onkeydown = function (e) {
    if (e.keyCode == "13") {
        e.preventDefault();
        scwin.fnSpclCalc();
    }
};

/**
 * 소가 inputBox onkeyDown Event
 * ASIS-fnCalcIjAmt 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_vsml_onkeydown = function (e) {
    if (e.keyCode == "13") {
        e.preventDefault();
        scwin.fnNormCalc();
    }
};

/* ==================================
* 5.custom Method 처리부
* ==================================*/

/**
 * 인지액 계산정보 setter Method
  * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.getStmpAmtCalcInfo = function (key) {
    return scwin.stmpAmtCalcInfo[key];
}

/**
 * 인지액 계산정보 getter Method
  * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.06.24.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.setStmpAmtCalcInfo = function (key, value) {
    scwin.stmpAmtCalcInfo[key] = value;
}

/**
* 인지액 계산 기본정보 조회
* ASIS-fnGetCalcBaseInfo
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.20.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.retrieveStmpCalcBasInfo = function () {
    com.executeSubmission(sbm_retrieveStmpCalcBasInfo);
}

/**
* 인지액 계산 기본정보 조회 submitdone event
* ASIS-fnGetCalcBaseInfo
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2024.06.23.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.sbm_retrieveStmpCalcBasInfo_submitdone = function (e) {
    var responseText = JSON.parse(e.responseText);
    var dataObj = responseText.data;
    var stmpAmtCalcBasInfo = dataObj.dma_stmpAmtCalcBasInfo;
    //조회 결과를 화면의 기본정보에 담는다.
    //조회 결과의 key와 화면의 기본정보 object에 만들어둔 key를 비교하여 같을 경우 값을 할당한다.
    Object.keys(stmpAmtCalcBasInfo).forEach(function (key1) {
        Object.keys(scwin.stmpAmtCalcInfo).forEach(function (key2) {
            if (key1 === key2) {
                scwin.stmpAmtCalcInfo[key2] = stmpAmtCalcBasInfo[key1];
            }
        })
    })
    //인지액 조정방식 및 특허소송 관련 문구의 변수를 세팅한다.
    spn_elctnDiscGuide.setValue(scwin.stmpAmtCalcInfo.stmpDiscEnfcYmd + scwin.phrsInfo.elctnDiscGuide);
    spn_ptntGuide.setValue(scwin.phrsInfo.ptntGuideTxt1 + scwin.stmpAmtCalcInfo.vsmlDisp + scwin.phrsInfo.ptntGuideTxt2
        + scwin.stmpAmtCalcInfo.stmpDisp + scwin.phrsInfo.ptntGuideTxt3);
    spn_ptntApplGuide.setValue(scwin.phrsInfo.ptntApplGuideTxt1 + scwin.stmpAmtCalcInfo.stmpDispSg + scwin.phrsInfo.ptntApplGuideTxt2);

    //문서작성번호가 존재하는 경우(납부화면에서 넘어온 경우)
    if (!scutilo.isEmpty(dma_parentInfo.get("elpEcdocNo"))) {
        scwin.retrieveDetailAmtInfo();
    } else {//초기 소송유형을 세팅하고 그에 따른 후처리를 한다.
        sbx_elctnLwstTaskTypCd.setValue(dma_parentInfo.get("elctnLwstTaskTypCd"));
        scwin.fnChangeLwstTaskTypCd();
        var ofdocDvsCd = dma_parentInfo.get("ofdocDvsCd");
        if ("" != ofdocDvsCd) {
            switch (ofdocDvsCd) {
                case psp.C.SO:
                    scwin.setStmpAmtCalcInfo("openPage", "SJ");
                    break;
                case psp.C.HANGSO:
                    scwin.setStmpAmtCalcInfo("openPage", "HS");
                    break;
                case psp.C.SANGGO:
                    scwin.setStmpAmtCalcInfo("openPage", "SG");
                    break;
                case psp.C.JOJUNGSIN:
                    scwin.setStmpAmtCalcInfo("openPage", "JJ");
                    break;
                case psp.C.HANGGO:
                case psp.C.JEAHANGGO:
                case psp.C.THANGGO:
                    scwin.setStmpAmtCalcInfo("openPage", "HG");
                    break;
                case psp.C.SINSA:
                case psp.C.JAESIMSIN:
                    scwin.setStmpAmtCalcInfo("openPage", "SC");
                    break;
            }
        }
        sbx_csType.setValue(scwin.getStmpAmtCalcInfo("openPage"));
        scwin.fnChangeCsTypCd();
        var vsmlAmt = dma_parentInfo.get("vsmlRslt");
        ibx_vsml.setValue(vsmlAmt);
        spn_localeVsmlAmt.setValue("(" + psputils.convertMoneytoStr(vsmlAmt) + ")");

        if (!scutilo.isEmpty(vsmlAmt)) {
            scwin.fnNormCalc();
        }
    }
};

/**
 * 인지액 계산 사건 상세 정보 조회
 * 해당 문서번호에 대한 사건의 상세 정보를 조회한다.
 * ASIS-fnGetDataIjAmt
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.28.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.retrieveDetailAmtInfo = function () {
    dma_search.set("elpEcdocNo", dma_parentInfo.get("elpEcdocNo"));
    dma_search.set("calcType", "stmpAmt");
    com.executeSubmission(sbm_retrieveCsCalcInfo);
}

/**
* 인지액 계산 사건 상세 정보 조회 submitdone event
* 상세 정보 조회 후 해당 사건 정보를 selectBox에서 선택하여 자동 계산하거나 직접 계산할 수 있도록 세팅한다.
* ASIS-fnGetDataIjAmt
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2024.06.23.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.sbm_retrieveCsCalcInfo_submitdone = function (e) {
    var elctnLwstTaskTypCd = dma_csCalcInfo.get("elctnLwstTaskTypCd");
    dma_parentInfo.set("elctnLwstTaskTypCd", elctnLwstTaskTypCd);
    var vsmlAmt = scutilo.isEmpty(dma_csCalcInfo.get("vsmlAmt")) ? "" : String(dma_csCalcInfo.get("vsmlAmt")); //소가
    var ofdocDvsCd = dma_csCalcInfo.get("ofdocDvsCd"); //문건구분코드
    var intgCsNmCd = dma_csCalcInfo.get("intgCsNmCd"); //통합사건명코드
    var tmprStndng = dma_csCalcInfo.get("imsi"); //임시지위여부
    var csType = dma_csCalcInfo.get("soType"); //사건구분
    var jaesimSinYN = dma_csCalcInfo.get("jaesimSinYN");

    sbx_elctnLwstTaskTypCd.setValue(elctnLwstTaskTypCd);
    scwin.fnChangeLwstTaskTypCd(csType);

    var isMatchHG = false;
    //항고재항고
    if (csType == "HG") {
        if ("Y" == jaesimSinYN) {
            sbx_apalDetailCsType.setValue("CANTFIX1");
            isMatchHG = true;
        } else {
            var stmpHanggoCsList = scwin.getStmpAmtCalcInfo("injiHanggoAmt");
            for (var i = 0; i < stmpHanggoCsList.length; i++) {
                if (tmprStndng == "Im") {//임시지위
                    if (intgCsNmCd == stmpHanggoCsList[i].saNmCd + "Im") {
                        sbx_apalDetailCsType.setValue(intgCsNmCd);
                        isMatchHG = true;
                        break;
                    }
                } else {
                    if (intgCsNmCd == stmpHanggoCsList[i].saNmCd) {
                        sbx_apalDetailCsType.setValue(intgCsNmCd);
                        isMatchHG = true;
                        break;
                    }
                }
            }
            if (!isMatchHG) {
                //그 외 사건
                sbx_apalDetailCsType.setValue("OTHERS");
            }
        }
        //항고대상사건변경 후처리 Method
        scwin.fnChangeApalTrgtCsType();
    }
    //신청사건
    if ("SC" == csType) {
        // 신청사건의 경우 준재심신청서의 경우 사건명코드로 판별할 수 없고 문건구분코드로 판별 가능함.
        if (psp.C.JAESIMSIN == ofdocDvsCd) {
            sbx_aplyDetailCsType.setValue("CANTFIX1");
            scwin.fnChangeAplyCsType();
        } else {
            var stmpAplyCsList = scwin.getStmpAmtCalcInfo("injiSinAmt");
            for (var i = 0; i < stmpAplyCsList.length; i++) {
                if ("Im" == tmprStndng) {//임시지위
                    if (intgCsNmCd == stmpAplyCsList[i].saNmCd + "Im") {
                        sbx_aplyDetailCsType.setValue(intgCsNmCd);
                        scwin.fnChangeAplyCsType();
                        break;
                    }
                } else {
                    if (intgCsNmCd == stmpAplyCsList[i].saNmCd) {
                        sbx_aplyDetailCsType.setValue(intgCsNmCd);
                        scwin.fnChangeAplyCsType();
                        break;
                    }
                }
            }
        }
    }

    ibx_vsml.setValue(scwin.extrNumberFromString(vsmlAmt));
    var amtLocaleString = psputils.convertMoneytoStr(scwin.extrNumberFromString(vsmlAmt));
    spn_localeVsmlAmt.setValue("(" + amtLocaleString + ")");

    if (!scutilo.isEmpty(csType) && !scutilo.isEmpty(vsmlAmt) && "SC" != csType) {
        scwin.fnNormCalc();
        ibx_vsml.blur();
    }
};

/**
* 소송유형 변경에 따른 후처리 Method
* 1. 소송유형 변경에 따라 인지액 계산 정보를 세팅한다.
* 2. 소송유형 변경에 따라 인지액 사건 정보를 세팅한다.(사건정보 selectBox)
* 3. 특정 사건정보가 param으로 넘어오는 경우 사건정보 selectBox에 해당 사건을 세팅한다.
* 4. 사건정보 변경에 따른 후처리 Method를 호출한다.
* ASIS-fnChgSosongTypcd
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.20.   김기오       [NELS]최초 생성
*  2024.02.27.   김기오       임시지위시 STRING CONCAT 추가
* ============= ============ ==========================
*/
scwin.fnChangeLwstTaskTypCd = function (docCsType) {
    var lwstTaskTypCd = sbx_elctnLwstTaskTypCd.getValue();
    var csType = sbx_csType.getValue();
    //행정
    if (psp.C.SO_KIND_PHS == lwstTaskTypCd) {
        scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimWHS"));
        scwin.setStmpAmtCalcInfo("injiHanggoAmt", scwin.getStmpAmtCalcInfo("injiHanggoAmtWHS"));
        scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHS"));
    }//특허
    else if (psp.C.SO_KIND_PPT == lwstTaskTypCd) {
        scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimWPT"));
        scwin.setStmpAmtCalcInfo("injiHanggoAmt", scwin.getStmpAmtCalcInfo("injiHanggoAmtWPT"));
        scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWPT"));
    }//회생파산
    else if (psp.C.SO_KIND_PHP == lwstTaskTypCd) {
        scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimWHP"));
        scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP1"));
        switch (csType) {
            case "PH":
                break;
            case "PF":
                scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimWHP"));
                scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP2"));
                break;
            case "BH":
                scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimWHP"));
                scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP3"));
                break;
            case "BF":
                scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimWHP"));
                scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP4"));
                break;
            case "NH":
                scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimWHP"));
                scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP5"));
                break;
        }
    }//민사집행
    else if (psp.C.SO_KIND_PJG == lwstTaskTypCd) {
        scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimJHWGJ"));
        scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ1"));
        switch (csType) {
            case "BK":
                break;
            case "CA":
                scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimJHWGJ"));
                scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ2"));
                break;
            case "CB":
                scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimJHWGJ"));
                scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ3"));
                break;
            case "JM":
                scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimJHWGJ"));
                scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ4"));
                break;
            case "JSCM":
                scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimJHWGJ"));
                scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ5"));
                break;
            case "GJ":
                scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimJHWGJ"));
                scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ6"));
                break;
        }
    }//과태료
    else if (psp.C.SO_KIND_PGW == lwstTaskTypCd) {
        scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimGW"));
        scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtGW1"));
    }//비송
    else if (psp.C.SO_KIND_PEB == lwstTaskTypCd) {
        scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimWETBS"));
        scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWETBS1"));
        if ("BSH" == csType) {
            scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWETBS2"));
        }
    } else {
        scwin.setStmpAmtCalcInfo("injiCalcBySim", scwin.getStmpAmtCalcInfo("injiCalcBySimWCV"));
        scwin.setStmpAmtCalcInfo("injiHanggoAmt", scwin.getStmpAmtCalcInfo("injiHanggoAmtWCV"));
        scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWCV"));
    }

    sbx_csType.removeAll();
    sbx_apalDetailCsType.removeAll();
    sbx_aplyDetailCsType.removeAll();

    dlt_csTypeList.removeAll();
    dlt_apalDetailCsTypeList.removeAll();
    dlt_aplyDetailCsTypeList.removeAll();

    var csTypeList = scwin.getStmpAmtCalcInfo("injiCalcBySim");
    var apalTypeList = scwin.getStmpAmtCalcInfo("injiHanggoAmt");
    var aplyTypeList = scwin.getStmpAmtCalcInfo("injiSinAmt");

    //사건 종류
    for (var i = 0; i < csTypeList.length; i++) {
        var rowData = {
            "label": csTypeList[i].simTxt,
            "value": csTypeList[i].simValue,
        }
        dlt_csTypeList.setRowJSON(i, rowData);
    }

    //회생파산 제외
    if (psp.C.SO_KIND_PHP != lwstTaskTypCd) {
        //항고재항고 사건리스트 세팅
        for (var j = 0; j < apalTypeList.length; j++) {
            //민사의 가처분, 가처분이의, 가처분취소 : 계쟁물과 임시지위로 나눠서 세팅
            if (psp.C.SO_KIND_PCV == lwstTaskTypCd &&
                (psp.C.BJGACHUSIN == apalTypeList[j].saNmCd || psp.C.BJGACHUIISIN == apalTypeList[j].saNmCd || psp.C.BJGACHUCNACEL == apalTypeList[j].saNmCd)) {
                var rowData1 = {
                    "label": apalTypeList[j].saTxt + "(계쟁물)",
                    "value": apalTypeList[j].saNmCd,
                }
                var rowData2 = {
                    "label": apalTypeList[j].saTxt + "(임시지위)",
                    "value": apalTypeList[j].saNmCd+"Im",
                }
                dlt_apalDetailCsTypeList.setRowJSON(dlt_apalDetailCsTypeList.getTotalRow(), rowData1);
                dlt_apalDetailCsTypeList.setRowJSON(dlt_apalDetailCsTypeList.getTotalRow(), rowData2);
            } else {
                var rowData = {
                    "label": apalTypeList[j].saTxt,
                    "value": apalTypeList[j].saNmCd,
                }
                dlt_apalDetailCsTypeList.setRowJSON(dlt_apalDetailCsTypeList.getTotalRow(), rowData);
            }
        }
    }

    //신청사건 종류
    for (var k = 0; k < aplyTypeList.length; k++) {
        //민사의 가처분, 가처분이의, 가처분취소 : 계쟁물과 임시지위로 나눠서 세팅
        if (psp.C.SO_KIND_PCV == lwstTaskTypCd &&
            (psp.C.BJGACHUSIN == aplyTypeList[k].saNmCd || psp.C.BJGACHUIISIN == aplyTypeList[k].saNmCd || psp.C.BJGACHUCNACEL == aplyTypeList[k].saNmCd)) {
            var rowData1 = {
                "label": aplyTypeList[k].saTxt + "(계쟁물)",
                "value": aplyTypeList[k].saNmCd,
            }
            var rowData2 = {
                "label": aplyTypeList[k].saTxt + "(임시지위)",
                "value": aplyTypeList[k].saNmCd+"Im",
            }
            dlt_aplyDetailCsTypeList.setRowJSON(dlt_aplyDetailCsTypeList.getTotalRow(), rowData1);
            dlt_aplyDetailCsTypeList.setRowJSON(dlt_aplyDetailCsTypeList.getTotalRow(), rowData2);
        } else {
            var rowData = {
                "label": aplyTypeList[k].saTxt,
                "value": aplyTypeList[k].saNmCd,
            }
            dlt_aplyDetailCsTypeList.setRowJSON(dlt_aplyDetailCsTypeList.getTotalRow(), rowData);
        }
    }

    if (!scutilo.isEmpty(docCsType)) {
        sbx_csType.setValue(docCsType);
    }
    //사건 종류 변경에 따른 처리
    scwin.fnChangeCsTypCd();
}

/**
* 사건구분 변경에 따른 처리 Method
* 1. 사건구분 변경에 따라 소가명, 조사, 인지액명을 세팅한다.
* 2. 사건구분 변경에 따라 신청 사건이나 대상 사건 정보를 세팅한다.(신청사건 selectBox, 대상사건 selectBox)
* 3. 사건구분 변경에 따른 후처리 Method를 호출한다.
* 4. 입력영역을 초기화 한다.(소가, 결과영역, 집행권원, 사용증명원 등)
* ASIS-fnSoTypeChange
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.28.   김기오       [NELS]최초 생성
*  2024.01.11.   김기오       신청사건시 누락 로직 추가
* ============= ============ ==========================
*/
scwin.fnChangeCsTypCd = function () {
    var csType = sbx_csType.getValue();
    var vsmlNm = "";//소가명
    var suffix = "";//조사

    var stmpCsList = scwin.getStmpAmtCalcInfo("injiCalcBySim");
    for (var i = 0; i < stmpCsList.length; i++) {
        if (stmpCsList[i].simValue == csType || "" == csType) {
            vsmlNm = stmpCsList[i].sogaNm;// 소가, 항소가, 상고가, 조정신청금액
            suffix = stmpCsList[i].sogaNmPad;// 조사(을/를)
            scwin.setStmpAmtCalcInfo("injiNm", stmpCsList[i].injiNm);// 인지액은, 항소사건 인지액은, 상고사건인지액은, 조정신청수수료는
            break;
        }
    }
    switch (csType) {
        //항고
        case "HG":
            tbx_calcGuide.setValue("사건 종류와 " + vsmlNm + suffix + " 선택해주세요.");
            sbx_apalDetailCsType.setSelectedIndex(0);
            grp_apalTrgtCsType.show("");
            grp_aplyCsType.hide("");
            grp_useCertf.hide("");
            grp_schld.hide("");
            scwin.fnChangeApalTrgtCsType();
            return;
        case "SC":
        case "PH":
        case "PF":
        case "BH":
        case "BF":
        case "NH":
            switch (csType) {//회생파산
                case "PH":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP1"));
                    break;
                case "PF":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP2"));
                    break;
                case "BH":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP3"));
                    break;
                case "BF":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP4"));
                    break;
                case "NH":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWHP5"));
                    break;
            }
            if ("SC" != csType) {
                dlt_aplyDetailCsTypeList.removeAll();
                var stmpAplyCsList = scwin.getStmpAmtCalcInfo("injiSinAmt");
                for (var i = 0; i < stmpAplyCsList.length; i++) {
                    var rowData = {
                        "label": stmpAplyCsList[i].saTxt,
                        "value": stmpAplyCsList[i].saNmCd,
                    };
                    dlt_aplyDetailCsTypeList.setRowJSON(i, rowData);
                }
            }
            tbx_calcGuide.setValue("사건 종류와 " + vsmlNm + suffix + " 선택해주세요.");
            var ofdocDvsCd = dma_csCalcInfo.get("ofdocDvsCd");
            if (psp.C.INHERFTPSSIN == ofdocDvsCd) {
                var aplyCsType = dma_csCalcInfo.get("sinType");
                sbx_aplyDetailCsType.setValue(aplyCsType);
            } else {
                sbx_aplyDetailCsType.setSelectedIndex(0);
            }
            grp_apalTrgtCsType.hide("");
            grp_aplyCsType.show("");
            grp_useCertf.hide("");
            grp_schld.hide("");
            scwin.fnChangeAplyCsType();
            return;
        case "BK":
        case "CA":
        case "CB":
        case "JM":
        case "JSCM":
        case "GJ":
        case "GW":
        case "BSD":
        case "BSH":
            switch (csType) {//집행비송
                case "BK":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ1"));
                    break;
                case "CA":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ2"));
                    break;
                case "CB":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ3"));
                    break;
                case "JM":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ4"));
                    break;
                case "JSCM":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ5"));
                    break;
                case "GJ":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtJHWGJ6"));
                    break;
                case "GW":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtGW1"));
                    break;
                case "BSD":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWETBS1"));
                    break;
                case "BSH":
                    scwin.setStmpAmtCalcInfo("injiSinAmt", scwin.getStmpAmtCalcInfo("injiSinAmtWETBS2"));
                    break;
            }
            dlt_aplyDetailCsTypeList.removeAll();
            var stmpAplyCsList = scwin.getStmpAmtCalcInfo("injiSinAmt");
            for (var i = 0; i < stmpAplyCsList.length; i++) {
                var rowData = {
                    "label": stmpAplyCsList[i].saTxt,
                    "value": stmpAplyCsList[i].saNmCd,
                };
                dlt_aplyDetailCsTypeList.setRowJSON(i, rowData);
            }
            tbx_calcGuide.setValue("사건 종류와 " + vsmlNm + suffix + " 선택해주세요.");

            sbx_aplyDetailCsType.setSelectedIndex(0);

            grp_apalTrgtCsType.hide("");
            grp_aplyCsType.show("");

            scwin.fnChangeAplyCsType();
            return;
        // 특허1심사건
        case "WPT":
        // 특허상고심사건
        case "SG_WPT":
            tbx_calcGuide.setValue("사건 종류" + suffix + " 선택해주세요.");
            grp_apalTrgtCsType.hide("");
            grp_aplyCsType.hide("");
            grp_vsml.show("");
            ibx_vsml.setDisabled(true);
            btn_normCalc.hide("");
            spn_rslt.setValue("");
            spn_vsml.setValue(vsmlNm);
            ibx_vsml.setTitle(vsmlNm);
            grp_useCertf.hide("");
            grp_schld.hide("");
            btn_spclCalc.hide("");
            scwin.fnChangePtntCsType();
            return;
        // 그 외
        default:
            tbx_calcGuide.setValue("사건 종류와 " + vsmlNm + suffix + " 입력하고 계산버튼을 눌러주세요.");
            grp_apalTrgtCsType.hide("");
            grp_aplyCsType.hide("");

            ibx_vsml.setDisabled(false);
            btn_normCalc.show("");
            grp_vsml.show("");

            grp_useCertf.hide("");
            grp_schld.hide("");

            btn_spclCalc.hide("");
            break;
    }
    spn_vsml.setValue(vsmlNm);
    ibx_vsml.setTitle(vsmlNm);
    ibx_vsml.setValue("");
    spn_localeVsmlAmt.setValue(" ( 원)");
    //ibx_vsml.focus("");
    spn_rslt.setValue("");
    ibx_useCertf.setValue("");
    ibx_schld.setValue("");
}

/**
* 항고 대상사건 변경에 따른 후처리 Method
* ASIS-fnHanggoTypeChange
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.07.05.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.fnChangeApalTrgtCsType = function () {
    var intgCsNmCd = sbx_apalDetailCsType.getValue();
    var stmpAmt = 0;

    var csTxt = dlt_apalDetailCsTypeList.getCellData(sbx_apalDetailCsType.getSelectedIndex(), "label");
    var elctnLwstTaskTypCd = sbx_elctnLwstTaskTypCd.getValue();
    //민사 가처분(임시지위), 가처분이의(임시지위), 가처분취소(임시지위), 제소전화해 신청서
    if (psp.C.SO_KIND_PCV == elctnLwstTaskTypCd && (psp.C.imsiGa == csTxt || psp.C.imsiGaIu == csTxt || psp.C.imsiGaCh == csTxt || psp.C.JESOJUNHOAHA == intgCsNmCd)) {
        ibx_vsml.setValue(""); // 인지액 입력값 초기화
        spn_localeVsmlAmt.setValue("( 원)"); // 인지액 한글 입력값표시 초기화
        //ibx_vsml.focus(); // 인지액 입력창 포커스
        grp_vsml.show("");
        ibx_vsml.setDisabled(false);
        btn_normCalc.show("");
        spn_rslt.setValue("");
        spn_vsml.setValue("소가");
        ibx_vsml.setTitle("소가");

        if (psp.C.JESOJUNHOAHA == intgCsNmCd) {
            spn_vsml.setValue("소가");
            ibx_vsml.setTitle("소가");
        }
    } else {
        ibx_vsml.setDisabled(false);
        grp_vsml.hide("");
        //sbx_apalDetailCsType.focus();
        spn_rslt.setValue("");

        var apalTypeList = scwin.getStmpAmtCalcInfo("injiHanggoAmt");

        for (var i = 0; i < apalTypeList.length; i++) {
            if (intgCsNmCd == apalTypeList[i].saNmCd) {
                stmpAmt = apalTypeList[i].injiAmt;
                break;
            }
        }
        //행정인 경우만 할인
        if (psp.C.SO_KIND_PHS == elctnLwstTaskTypCd) {
            stmpAmt = parseInt(stmpAmt / 100) * 100; //절사
            stmpAmt = stmpAmt * Number(scwin.getStmpAmtCalcInfo("stmpDiscRate")); //할인 적용
            stmpAmt = parseInt(stmpAmt / 100) * 100; //절사
        }

        if (psp.C.SO_KIND_PCV == elctnLwstTaskTypCd &&
            (psp.C.BJGAAPSIN == intgCsNmCd || psp.C.BJGAAPCNACEL == intgCsNmCd || psp.C.BJGAAPIISIN == intgCsNmCd || psp.C.BJGACHUSIN == intgCsNmCd
                || psp.C.BJGACHUCNACEL == intgCsNmCd || psp.C.BJGACHUIISIN == intgCsNmCd || psp.C.JUTAEKIMCHAGWON == intgCsNmCd || psp.C.SANGGAIMCHAGWON == intgCsNmCd
                || psp.C.JUTAEKIMCHAII == intgCsNmCd || psp.C.SANGGAIMCHAII == intgCsNmCd || psp.C.JESOJUNHOAHA == intgCsNmCd)) {
            stmpAmt = stmpAmt * 2;
        }


        var commaStmpAmt = scwin.getDotFormattedNumber(Number(stmpAmt).toFixed(0), 3, "원");
        var amtLocaleString = psputils.convertMoneytoStr((Number(stmpAmt).toFixed(0)).toString());

        spn_rslt.setValue(scwin.getStmpAmtCalcInfo("injiNm") + ' <b><font color="045abd">' + commaStmpAmt + " (" + amtLocaleString + ")</font></b>" + "입니다. (10% 할인된 금액)");
    }
}

/**
* 신청사건 종류 변경에 따른 후처리 Method
