*/
scwin.fnChangeAplyCsType = function () {
    var intgCsNmCd = sbx_aplyDetailCsType.getValue();
    var stmpAmt = 0;
    var csTxt = dlt_aplyDetailCsTypeList.getCellData(sbx_aplyDetailCsType.getSelectedIndex(), "label");

    var elctnLwstTaskTypCd = sbx_elctnLwstTaskTypCd.getValue();
    //민사 가처분(임시지위), 가처분이의(임시지위), 가처분취소(임시지위)
    if (psp.C.SO_KIND_PCV == elctnLwstTaskTypCd && (psp.C.imsiGa == csTxt || psp.C.imsiGaIu == csTxt || psp.C.imsiGaCh == csTxt)) {
        ibx_vsml.setValue(""); // 인지액 입력값 초기화
        spn_localeVsmlAmt.setValue("( 원)"); // 인지액 한글 입력값표시 초기화
        //ibx_vsml.focus(); // 인지액 입력창 포커스
        grp_vsml.show("");
        ibx_vsml.setDisabled(false);
        btn_normCalc.show("");
        spn_rslt.setValue("");
        spn_vsml.setValue("소가");
        ibx_vsml.setTitle("소가");
    }
    //민사집행
    else if (psp.C.SO_KIND_PJG == elctnLwstTaskTypCd &&
        (psp.C.BUDONGSANGJGMSIN_NM == csTxt || psp.C.JADONGCHAGJGMSIN_NM == csTxt || psp.C.GUNSULGIGGJGMSIN_NM == csTxt
            || psp.C.SUNBAKGJGMSIN_NM == csTxt || psp.C.HANGONGGIGJGMSIN_NM == csTxt || psp.C.GWANGUPGWANGJGMSIN_NM == csTxt
            || psp.C.UPUPGWONGJGMSIN_NM == csTxt || psp.C.SOSUNBAKGJGMSIN_NM == csTxt
            || psp.C.BUDONGSANIMGMSIN_NM == csTxt || psp.C.JADONGCHAIMGMSIN_NM == csTxt || psp.C.GUNSULGIGIMGMSIN_NM == csTxt
            || psp.C.SUNBAKIMGMSIN_NM == csTxt || psp.C.HANGONGGIIMGMSIN_NM == csTxt || psp.C.GWANGUPGWANIMGMSIN_NM == csTxt
            || psp.C.UPUPGWONIMGMSIN_NM == csTxt || psp.C.SOSUNBAKIMGMSIN_NM == csTxt
        )) {//강제경매 신청서
        ibx_useCertf.setValue("");
        grp_useCertf.show("");
        ibx_schld.setValue("");
        btn_spclCalc.show("");
        grp_schld.show("");

        ibx_vsml.setDisabled(false);
        btn_normCalc.hide("");
        grp_vsml.hide("");

        spn_rslt.setValue("");
        //ibx_useCertf.focus();
        //sbx_aplyDetailCsType.focus();

    } else if (psp.C.SO_KIND_PJG == elctnLwstTaskTypCd &&
        (psp.C.CHAEGWONARCSMRSIN_NM == csTxt || psp.C.GARBARIUJCGARCSMRSIN_NM == csTxt
            || psp.C.CHAEGWONARJBMRSIN_NM == csTxt || psp.C.GARBARIUJCGARJBMRSIN_NM == csTxt
        )) {//채권압류 및 추심명령 신청서, 가압류를 본압류로 이전하는 채권압류 및 추심명령 신청서, 채권압류 및 전부명령 신청서 신청서, 가압류를 본압류로 이전하는 채권압류 및 전부명령 신청서
        ibx_useCertf.setValue("");
        grp_useCertf.hide("");

        ibx_schld.setValue("");
        btn_spclCalc.show("");
        grp_schld.show("");
        //ibx_schld.focus();

        ibx_vsml.setDisabled(false);
        btn_normCalc.hide("");
        grp_vsml.hide("");

        spn_rslt.setValue("");
    } else {

        ibx_useCertf.setValue("");
        grp_useCertf.hide("");

        ibx_schld.setValue("");
        btn_spclCalc.hide("");
        grp_schld.hide("");

        ibx_vsml.setDisabled(false);
        btn_normCalc.hide("");
        grp_vsml.hide("");

        spn_rslt.setValue("");

        //sbx_aplyDetailCsType.focus();

        var aplyTypeList = scwin.getStmpAmtCalcInfo("injiSinAmt");

        for (var i = 0; i < aplyTypeList.length; i++) {
            if (intgCsNmCd == aplyTypeList[i].saNmCd) {
                stmpAmt = aplyTypeList[i].injiAmt;
                break;
            }
        }
        //행정인 경우만 할인
        if (psp.C.SO_KIND_PHS == elctnLwstTaskTypCd) {
            stmpAmt = parseInt(stmpAmt / 100) * 100; //절사
            stmpAmt = stmpAmt * Number(scwin.getStmpAmtCalcInfo("stmpDiscRate")); //할인 적용
            stmpAmt = parseInt(stmpAmt / 100) * 100; //절사
        }

        var commaStmpAmt = scwin.getDotFormattedNumber(Number(stmpAmt).toFixed(0), 3, "원");
        var amtLocaleString = psputils.convertMoneytoStr((Number(stmpAmt).toFixed(0)).toString());

        spn_rslt.setValue(scwin.getStmpAmtCalcInfo("injiNm") + ' <b><font color="045abd">' + commaStmpAmt + " (" + amtLocaleString + ")</font></b>" + "입니다. (10% 할인된 금액)");
    }
}

/**
* 특허1심사건과 특허상고심사건의 인지액 계산 Method
* ASIS-fnWptTypeChange
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.07.06.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.fnChangePtntCsType = function () {
    var csType = sbx_csType.getValue();
    var vsmlAmt = 0;
    var stmpAmt = 0;
    var ptntCsList = scwin.getStmpAmtCalcInfo("injiWptAmt");

    for (var i = 0; i < ptntCsList.length; i++) {
        if (csType == ptntCsList[i].soType) {
            vsmlAmt = ptntCsList[i].amt;
            stmpAmt = ptntCsList[i].injiAmt;
            break;
        }
    }

    var strVsmlAmt = String(vsmlAmt).replace(/,/g, "");
    if (strVsmlAmt != "") {
        ibx_vsml.setValue(scwin.extrNumberFromString(strVsmlAmt));
        spn_localeVsmlAmt.setValue("(" + psputils.convertMoneytoStr(scwin.extrNumberFromString(strVsmlAmt)) + ")");
    }
    var commaStmpAmt = scwin.getDotFormattedNumber(Number(stmpAmt).toFixed(0), 3, "원");
    var amtLocaleString = psputils.convertMoneytoStr((Number(stmpAmt).toFixed(0)).toString());

    spn_rslt.setValue(scwin.getStmpAmtCalcInfo("injiNm") + ' <b><font color="045abd">' + commaStmpAmt + " (" + amtLocaleString + ")</font></b>" + "입니다. (10% 할인된 금액)");
}
/*
**
* 인지액 계산 Method(일반)
* ASIS-fnCalcIjAmt
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.07.06.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.fnNormCalc = async function () {
    //2023 0725 psp.validate => 직접 체크하는 것으로(focus issue)
    if (scutilo.isEmpty(ibx_vsml.getValue())) {
        var msg = scutilo.getMsg(pspmsg.PSP.W_1001, "" + ibx_vsml.getTitle() + "");
        await psp.showMsg(scglblo.MSG.WARN, msg, () => { ibx_vsml.focus(); });
        return false;
    }

    var strVsmlAmt = ibx_vsml.getValue().replace(/,/g, "");
    var lwstTaskTypCd = sbx_elctnLwstTaskTypCd.getValue();

    if (!scwin.isCombineNum(strVsmlAmt) && strVsmlAmt != "") {
        scutilo.showMsg("경고", scutilo.getMsg(pspmsg.PSP.W_0238));

        //20230708 - #,### format의 data는 Number input에 넣을 시 값이 변한다.
        //ibx_vsml.setValue(psputils.formatMoney(scwin.extrNumberFromString(strVsmlAmt)));
        ibx_vsml.setValue(scwin.extrNumberFromString(strVsmlAmt));
        spn_localeVsmlAmt.setValue("(" + psputils.convertMoneytoStr(scwin.extrNumberFromString(strVsmlAmt)) + ")");
        //ibx_vsml.focus();

        return false;
    }

    var csType = sbx_csType.getValue();
    var intVsmlAmt = Number(strVsmlAmt);
    var intStmp = 0;
    var stmpDiscRate = scwin.getStmpAmtCalcInfo("stmpDiscRate");

    var calfByAmt = scwin.getStmpAmtCalcInfo("injiCalcByAmt"); //금액대에 따른 계산식
    var calfByInscrt = scwin.getStmpAmtCalcInfo("injiCalcBySim");//심급에 따른 계산식

    //1. 금액대별 인지액 계산
    for (var i = 0; i < calfByAmt.length; i++) {
        if (calfByAmt[i].minAmt <= intVsmlAmt && calfByAmt[i].maxAmt > intVsmlAmt) {
            intStmp = scwin.multiplyDouble(intVsmlAmt, Number(calfByAmt[i].multiValue)) + Number(calfByAmt[i].sumValue);
            break;
        }
    }

    //2. 심급별 인지액 계산
    for (var i = 0; i < calfByInscrt.length; i++) {
        if (calfByInscrt[i].simValue == csType) {
            //조정신청은 할인안함
            if (csType == "JJ") {
                intStmp = intStmp * Number(calfByInscrt[i].multiBeforeTrim);// 절사전 조정신청은 1/5로 금액 조정
                intStmp = (intStmp < 1000) ? 1000 : parseInt(intStmp / 100) * 100;// 인지액 천원미만 => 천원, 천원이상 => 백원미만 절사

                //머, 재머 사건일 경우에도 인지액 10% 감액되도록 수정
                intStmp = intStmp * Number(stmpDiscRate); //할인 적용
                intStmp = parseInt(intStmp / 100) * 100; //절사
            } // 나머지는 할인
            else {
                // 지급명령일 경우 계산식 추가
                if ("DC" == calfByInscrt[i].simValue) {
                    intStmp = intStmp / 10;
                }
                intStmp = (intStmp < 1000) ? 1000 : parseInt(intStmp / 100) * 100;// 인지액 천원미만 => 천원, 천원이상 => 백원미만 절사
                intStmp = intStmp * Number(calfByInscrt[i].multiAfterTrim);//항소심1.5배, 상고심2배
                intStmp = parseInt(intStmp / 100) * 100; //절사

                //민사소송일때 항고/신청사건 관련 수정
                if (psp.C.SO_KIND_PCV == lwstTaskTypCd) {
                    //항고
                    if ("HG" == csType) {
                        var csTxt = dlt_apalDetailCsTypeList.getCellData(sbx_apalDetailCsType.getSelectedIndex(), "label");
                        var intgCsNmCd = sbx_apalDetailCsType.getValue();

                        if (psp.C.imsiGa == csTxt || psp.C.imsiGaIu == csTxt || psp.C.imsiGaCh == csTxt) {
                            intStmp = intStmp / 2;
                            if (intStmp > 500000) intStmp = 500000;//본안의 소에 따른 인지액의 2분의 1(인지액의 상한액은 50만원)
                            intStmp = intStmp * Number(stmpDiscRate); //할인 적용
                            intStmp = parseInt(intStmp / 100) * 100; //절사
                            intStmp = intStmp * 2;
                        }
                        if (psp.C.JESOJUNHOAHA == intgCsNmCd) {
                            intStmp = intStmp * 0.2;
                            if (intStmp < 1000) intStmp = 1000;
                            intStmp = intStmp * Number(stmpDiscRate); //할인 적용
                            intStmp = parseInt(intStmp / 100) * 100; //절사
                            intStmp = intStmp * 2;
                        }
                    } //신청
                    else if ("SC" == csType) {
                        var intgCsNmCd = sbx_aplyDetailCsType.getValue();
                        var csTxt = dlt_aplyDetailCsTypeList.getCellData(sbx_aplyDetailCsType.getSelectedIndex(), "label");

                        if (psp.C.imsiGa == csTxt || psp.C.imsiGaIu == csTxt || psp.C.imsiGaCh == csTxt) {
                            intStmp = intStmp / 2;
                            if (intStmp > 500000) intStmp = 500000;//본안의 소에 따른 인지액의 2분의 1(인지액의 상한액은 50만원)
                            intStmp = intStmp * Number(stmpDiscRate); //할인 적용
                            intStmp = parseInt(intStmp / 100) * 100; //절사
                        }
                    } else if ("JH" == csType) {  // 제소전화해 민사 소가 계산에 따른 인지의 5분의 1
                        intStmp = intStmp / 5;
                        if (intStmp < 1000) intStmp = 1000;
                        intStmp = intStmp * Number(stmpDiscRate); //할인 적용
                        intStmp = parseInt(intStmp / 100) * 100; //절사
                    } else {
                        intStmp = intStmp * Number(stmpDiscRate); //할인 적용
                        intStmp = parseInt(intStmp / 100) * 100; //절사
                    }
                } else {
                    intStmp = intStmp * Number(stmpDiscRate); //할인 적용
                    intStmp = parseInt(intStmp / 100) * 100; //절사
                }
            }
            break;
        }
    }
    intStmp = parseInt(intStmp / 100) * 100; //절사

    var commaStmpAmt = scwin.getDotFormattedNumber(intStmp.toFixed(0), 3, "원");
    var amtLocaleString = psputils.convertMoneytoStr((intStmp.toFixed(0)).toString());

    if ("JJ" == csType) {//조정신청은 할인안함 - 문구 표시 안함
        spn_rslt.setValue(scwin.getStmpAmtCalcInfo("injiNm") + ' <b><font color="045abd">' + commaStmpAmt + " (" + amtLocaleString + ")</font></b>" + "입니다.");
    } else {
        spn_rslt.setValue(scwin.getStmpAmtCalcInfo("injiNm") + ' <b><font color="045abd">' + commaStmpAmt + " (" + amtLocaleString + ")</font></b>" + "입니다. (10% 할인된 금액)");
    }
}

/*
**
* 집행권원, 사용증명원 계산
* ASIS-fnCalcIjAmt1
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.07.06.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.fnSpclCalc = async function () {
    var strUseAmt = ibx_useCertf.getValue().replace(/,/g, "");
    var strSchldAmt = ibx_schld.getValue().replace(/,/g, "");
    var lwstTaskTypCd = sbx_elctnLwstTaskTypCd.getValue();
    var csTxt = dlt_aplyDetailCsTypeList.getCellData(sbx_aplyDetailCsType.getSelectedIndex(), "label");

    var intUseAmt = Number(strUseAmt);
    var intSchldAmt = Number(strSchldAmt);
    var intStmp = 0;
    var stmpDiscRate = scwin.getStmpAmtCalcInfo("stmpDiscRate");
    //민사집행
    if (psp.C.SO_KIND_PJG == lwstTaskTypCd
        && (psp.C.BUDONGSANGJGMSIN_NM == csTxt || psp.C.JADONGCHAGJGMSIN_NM == csTxt || psp.C.GUNSULGIGGJGMSIN_NM == csTxt
            || psp.C.SUNBAKGJGMSIN_NM == csTxt || psp.C.HANGONGGIGJGMSIN_NM == csTxt || psp.C.GWANGUPGWANGJGMSIN_NM == csTxt
            || psp.C.UPUPGWONGJGMSIN_NM == csTxt || psp.C.SOSUNBAKGJGMSIN_NM == csTxt
            || psp.C.BUDONGSANIMGMSIN_NM == csTxt || psp.C.JADONGCHAIMGMSIN_NM == csTxt || psp.C.GUNSULGIGIMGMSIN_NM == csTxt
            || psp.C.SUNBAKIMGMSIN_NM == csTxt || psp.C.HANGONGGIIMGMSIN_NM == csTxt || psp.C.GWANGUPGWANIMGMSIN_NM == csTxt
            || psp.C.UPUPGWONIMGMSIN_NM == csTxt || psp.C.SOSUNBAKIMGMSIN_NM == csTxt)
    ) {//강제경매
        if (scutilo.isEmpty(ibx_useCertf.getValue())) {
            var msg = scutilo.getMsg(pspmsg.PSP.W_1001, "" + ibx_useCertf.getTitle() + "");
            await psp.showMsg(scglblo.MSG.WARN, msg, () => { });
            //ibx_useCertf.focus();
            return false;
        }

        if (scutilo.isEmpty(ibx_schld.getValue())) {
            var msg = scutilo.getMsg(pspmsg.PSP.W_1001, "" + ibx_schld.getTitle() + "");
            await psp.showMsg(scglblo.MSG.WARN, msg, () => { });
            ibx_schld.focus();
            return false;
        }

        if (!scwin.isCombineNum(strUseAmt) && strUseAmt != "") {
            //숫자타입이 아닙니다.
            await psp.showMsg("경고", scutilo.getMsg(pspmsg.PSP.W_0238));
            ibx_useCertf.setValue(psputils.formatMoney(scwin.extrNumberFromString(strUseAmt)))
            ibx_useCertf.focus();
            return false;
        }

        if (!scwin.isCombineNum(strSchldAmt) && strSchldAmt != "") {
            //숫자타입이 아닙니다.
            await psp.showMsg("경고", scutilo.getMsg(pspmsg.PSP.W_0238));
            ibx_schld.setValue(psputils.formatMoney(scwin.extrNumberFromString(strSchldAmt)))
            ibx_schld.focus();
            return false;
        }

        // 집행권원 사용증명원 비용 450원으로 수정
        if (intSchldAmt == 0) {
            intStmp = (intUseAmt * 450) + (5000 * Number(stmpDiscRate));
        } else {
            intStmp = (intUseAmt * 450) + (5000 * intSchldAmt * Number(stmpDiscRate));
        }
    }

    else if (psp.C.SO_KIND_PJG == lwstTaskTypCd
        && (psp.C.CHAEGWONARCSMRSIN_NM == csTxt || psp.C.GARBARIUJCGARCSMRSIN_NM == csTxt)
    ) {	//채권압류 및 추심명령 신청서, 가압류를 본압류로 이전하는 채권압류 및 추심명령 신청서
        //if (!chk2.isValid()) return false;

        if (scutilo.isEmpty(ibx_schld.getValue())) {
            var msg = scutilo.getMsg(pspmsg.PSP.W_1001, "" + ibx_schld.getTitle() + "");
            await psp.showMsg(scglblo.MSG.WARN, msg, () => { });
            ibx_schld.focus();
            return false;
        }

        if (!scwin.isCombineNum(strSchldAmt) && strSchldAmt != "") {
            //숫자타입이 아닙니다.
            await psp.showMsg("경고", scutilo.getMsg(pspmsg.PSP.W_0238));
            ibx_schld.setValue(psputils.formatMoney(scwin.extrNumberFromString(strSchldAmt)))
            ibx_schld.focus();

            return false;
        }

        if (intSchldAmt == 0) {
            intStmp = 4000 * Number(stmpDiscRate);
        } else {
            intStmp = 4000 * intSchldAmt * Number(stmpDiscRate);
        }
    }

    else if (psp.C.SO_KIND_PJG == lwstTaskTypCd
        && (psp.C.CHAEGWONARJBMRSIN_NM == csTxt || psp.C.GARBARIUJCGARJBMRSIN_NM == csTxt)
    ) {	//채권압류 및 전부명령 신청서 신청서, 가압류를 본압류로 이전하는 채권압류 및 전부명령 신청서

        //if (!chk2.isValid()) return false;

        if (scutilo.isEmpty(ibx_schld.getValue())) {
            var msg = scutilo.getMsg(pspmsg.PSP.W_1001, "" + ibx_schld.getTitle() + "");
            await psp.showMsg(scglblo.MSG.WARN, msg, () => { });
            ibx_schld.focus();
            return false;
        }

        if (!scwin.isCombineNum(strSchldAmt) && strSchldAmt != "") {
            //숫자타입이 아닙니다.
            await psp.showMsg("경고", scutilo.getMsg(pspmsg.PSP.W_0238));
            ibx_schld.setValue(psputils.formatMoney(scwin.extrNumberFromString(strSchldAmt)))
            ibx_schld.focus();

            return false;
        }

        if (intSchldAmt == 0) {
            intStmp = 4000 * Number(stmpDiscRate);
        } else {
            intStmp = ((2000 * intSchldAmt) + 2000) * Number(stmpDiscRate);
        }
    }


    var amtLocaleString = psputils.convertMoneytoStr((intStmp.toFixed(0)).toString());

    var commaStmpAmt = scwin.getDotFormattedNumber(intStmp.toFixed(0), 3, "원");
    var amtLocaleString = psputils.convertMoneytoStr((intStmp.toFixed(0)).toString());

    spn_rslt.setValue(scwin.getStmpAmtCalcInfo("injiNm") + ' <b><font color="045abd">' + commaStmpAmt + " (" + amtLocaleString + ")</font></b>" + "입니다. (10% 할인된 금액)");

}

/*
 * 금액 입력 시, 숫자 검사 및 문자형 금액 입력
 * ASIS-ecf304.fnInputAmtMoney
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.07.14.    김기오         [NELS] 최초생성
 * ============= ============ ==========================
 */
scwin.fnChkVsmlInput = function (option, e) {

    if(e.keyCode > 36 && e.keyCode < 41) return;

    var ibxObj = option == "useCertf" ? ibx_useCertf : option == "schld" ? ibx_schld : ibx_vsml;
    var strVsmlAmt = ibxObj.getValue().replace(/,/g, "");
    if (!scwin.isCombineNum(strVsmlAmt) && strVsmlAmt != "") {
        scutilo.showMsg("경고", scutilo.getMsg(pspmsg.PSP.W_0238));

        //20230708 - #,### format의 data는 Number input에 넣을 시 값이 변한다.
        //ibx_vsml.setValue(psputils.formatMoney(scwin.extrNumberFromString(strVsmlAmt)));
        ibxObj.setValue(scwin.extrNumberFromString(strVsmlAmt));
        if (option == 3) {
            spn_localeVsmlAmt.setValue("(" + psputils.convertMoneytoStr(scwin.extrNumberFromString(strVsmlAmt)) + ")");
        }
        ibxObj.focus();

        return false;
    }

    var numbers = "";
    numbers = scwin.extrNumberFromString(ibx_vsml.getValue());

    ibx_vsml.setValue(numbers);
    spn_localeVsmlAmt.setValue("(" + psputils.convertMoneytoStr(numbers) + ")");
}

/**
 * 문자열에서 숫자만 추출한다.
 * ASIS-ECF000.cfEcfGetNumber
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.06.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.extrNumberFromString = function (str) {
    var numStr = "";
    var i = 0;
    var j = 0;

    for (i = 0; i < str.length; i++) {
        for (j = 0; j <= 9; j++) {
            if (str.substr(i, 1) == " ") {
                break;
            }

            if (str.substr(i, 1) == j) {
                numStr = numStr + str.substr(i, 1);
                break;
            }
        }
        str.substr(i, 1);
    }

    return numStr;
}

/**
 * 금액 콤마처리 Method
 * ASIS-ECF000.cfDotNum
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.23.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.getDotFormattedNumber = function (paramNum, thresholdPoint, suffixStr) {
    var numToStr = "";
    var strLength = 0;
    var formattedResult = "";

    if (isNaN(paramNum)) {
        return "0" + suffixStr;
    }

    numToStr = paramNum.toString();
    strLength = numToStr.length;

    if (strLength > thresholdPoint) {
        for (var i = 0; i < strLength; i++) {
            if (((strLength - i) % thresholdPoint) == 0 && i != 0) {
                formattedResult += "," + numToStr.substr(i, 1);
            } else {
                formattedResult += numToStr.substr(i, 1);
            }
        }
        formattedResult += suffixStr;
    } else {
        formattedResult = numToStr + suffixStr;
    }
    return formattedResult;
}

/*
 * 숫자로만 구성되어있는지 확인
 * ASIS-du.core.js(du.chk.isNum)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.07.06.    김기오         [NELS] 최초생성
 * ============= ============ ==========================
 *
 */
scwin.isCombineNum = function (str) {
    if (null == str || undefined == str || !(typeof str == "string")) {
        return false;
    }
    return /[0-9]/g.test(str) && str.replace(/[0-9]/g, "").length == 0;
}

/*
 * 소수점 곱셈 계산(자바스크립트의 소수점 연산 오류 해결을 위해 사용)
 * ASIS-ecf304_1.js(multiply)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.07.06.    김기오         [NELS] 최초생성
 * ============= ============ ==========================
 */
scwin.multiplyDouble = function (double1, double2) {
    var str1 = double1 + "";
    var str2 = double2 + "";

    var decimalPoint1 = str1.indexOf(".");
    var decimalPoint2 = str2.indexOf(".");

    var decimalSize1 = decimalPoint1 < 0 ? 0 : str1.length - decimalPoint1 - 1;
    var decimalSize2 = decimalPoint2 < 0 ? 0 : str2.length - decimalPoint2 - 1;

    var power1 = Math.pow(10.0, decimalSize1);
    var power2 = Math.pow(10.0, decimalSize2);

    return (double1 * power1).toFixed(0) * (double2 * power2).toFixed(0) / (power1 * power2);
}
